<script setup lang="ts">import { computed } from 'vue';import { RouterLink } from 'vue-router';import AppIcon from '../../components/AppIcon.vue';const props=withDefaults(defineProps<{statusCode?:number}>(),{statusCode:404});const copy=computed(()=>props.statusCode===403?['此区域需要相应权限','当前账户无权访问。站点协调员只能处理授权站点，管理员能力也会记录审计。']:props.statusCode===500?['服务暂时没有回应','请求关联 ID 会帮助管理员定位问题。请稍后重试，页面不会向你暴露服务器堆栈。']:props.statusCode===0?['当前处于离线状态','网络恢复后可重新加载。未提交的发布内容仍保存在本机草稿中。']:['这条线索不在这里','页面可能已移动、关闭或从未存在。请从公开广场重新查找。'])</script>
